yakit.AutoInitYakit()

# Input your code!


RespRaw = cli.String("Response", cli.setDefault("hello world!"))
ishttps = cli.Bool("ishttps", cli.setDefault(false))
port = cli.Int("port", cli.setDefault(8888))
Head = cli.String("Head", cli.setDefault(`{"Content-Type":"text/html"}`))
cli.check()

print(ishttps)



httpServer = func(){
    if ishttps{
        ca, priKey, err = tls.GenerateRootCA("http")
        if err != nil{
            yakit.Warn("生成CA证书失败！！！！！")
            die(err)
        }

        scer, skey, err = tls.SignServerCertAndKey(ca, priKey)

        if err != nil{
            yakit.Warn("生成服务端证书失败！！！！！")
            die(err)
        }

        if os.IsTCPPortOpen(port){
            yakit.Warn("%v 端口已被占用，替换随机端口。"%port)
            port = os.GetRandomAvailableTCPPort()
        }
        yakit.Info("https服务器开启 0.0.0.0:%v,"%port)
        httpserver.Serve("0.0.0.0", port, httpserver.handler(respHandler),httpserver.tlsCertAndKey(scer, skey))
    }else{
        if os.IsTCPPortOpen(port){
            yakit.Warn("%v 端口已被占用，替换随机端口。"%port)
            port = os.GetRandomAvailableTCPPort()
        }
        yakit.Info("http服务器开启 0.0.0.0:%v,"%port)
        httpserver.Serve("0.0.0.0", port, httpserver.handler(respHandler))

    }
}

respHandler = func(w,r){
    Head = json.loads(Head)
    for k, v = range Head{
        w.Header().Add(k, v)
    }
    io.WriteString(w, RespRaw)
    risk.NewRisk(r.RemoteAddr,
        risk.description("http请求"),
        risk.solution("test"),
        risk.level("low"),
        risk.title("来自%s的http请求"%r.RemoteAddr),
        risk.titleVerbose("来自%s的http请求"%r.RemoteAddr),
        risk.type("http平台插件请求！"),
        risk.request(string(http.dump(r)[0])),
        risk.details({"备注":"http平台收到请求！！"})
    )
}

httpServer()
